/** Muted identification colours of projects (key → label, hex), same palette as the web app. */
data class ProjectColorDefinition(val key: String, val label: String, val hex: Long) {
    companion object {
        val all: List<ProjectColorDefinition> = listOf(
            ProjectColorDefinition("slate", "Grau", 0x8E8E93),
            ProjectColorDefinition("blue", "Blau", 0x4A7FD4),
            ProjectColorDefinition("teal", "Petrol", 0x3A9A9A),
            ProjectColorDefinition("green", "Grün", 0x4F9A5C),
            ProjectColorDefinition("amber", "Ocker", 0xC49A3A),
            ProjectColorDefinition("orange", "Orange", 0xD2793F),
            ProjectColorDefinition("red", "Rot", 0xC95353),
            ProjectColorDefinition("pink", "Rosa", 0xC46A93),
            ProjectColorDefinition("purple", "Violett", 0x8A6CC4),
        )

        /** Unknown keys fall back to grey (as on the web). */
        fun forKey(key: String): ProjectColorDefinition = all.firstOrNull { it.key == key } ?: all[0]
    }
}

